"""Exercise real offline UI, bridge continuity, dynamics and model exports."""
from pathlib import Path
import json,struct
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs';checks={};errors=[]
def check(name,value):
 checks[name]=bool(value);print(('PASS ' if value else 'FAIL ')+name,flush=True)
 assert value,name
with sync_playwright() as p:
 ctx=p.chromium.launch_persistent_context(str(OUT/'qa-browser-profile'),channel='msedge',headless=True,args=['--enable-webgl','--enable-unsafe-swiftshader'],viewport={'width':1280,'height':850},device_scale_factor=1,accept_downloads=True)
 ctx.set_offline(True);page=ctx.new_page();requests=[];page.on('request',lambda r:requests.append(r.url));page.on('pageerror',lambda e:errors.append(str(e)));page.on('console',lambda m:errors.append(m.text) if m.type=='error' else None)
 page.goto((ROOT/'衡联总部.html').as_uri(),wait_until='networkidle');page.wait_for_function('window.headquartersApp?.ready',polling=100,timeout=120000);page.wait_for_function('headquartersApp.metrics().frames>15',polling=100,timeout=120000)
 check('offline single HTML',not any(r.startswith(('http:','https:')) for r in requests))
 check('two editable buildings and independent bridge',page.evaluate("headquartersApp.model.buildings.size===2&&headquartersApp.model.groups.has('bridge')&&headquartersApp.model.manifest.buildings.map(b=>b.floors).join(',')==='24,16'"))
 check('100m main and 68m annex',page.evaluate("headquartersApp.model.manifest.buildings.map(b=>b.height).join(',')==='100,68'"))
 page.click('#pause');t=page.evaluate('headquartersApp.model.simulationTime');page.wait_for_timeout(250);check('pause freezes motion',t==page.evaluate('headquartersApp.model.simulationTime'));page.click('#pause');page.wait_for_timeout(250);check('resume advances motion',page.evaluate('headquartersApp.model.simulationTime')>t)
 before=page.evaluate('headquartersApp.camera.position.toArray()');page.mouse.move(640,560);page.mouse.down();page.mouse.move(750,610,steps=10);page.mouse.up();page.wait_for_timeout(250);check('drag rotates',before!=page.evaluate('headquartersApp.camera.position.toArray()'))
 before=page.evaluate('headquartersApp.controls.target.toArray()');page.mouse.move(640,560);page.mouse.down(button='right');page.mouse.move(690,580,steps=8);page.mouse.up(button='right');page.wait_for_timeout(250);check('right drag pans',before!=page.evaluate('headquartersApp.controls.target.toArray()'))
 zoom=page.evaluate('headquartersApp.camera.zoom');page.mouse.move(640,560);page.mouse.wheel(0,-250);page.wait_for_timeout(200);check('wheel zooms',page.evaluate('headquartersApp.camera.zoom')>zoom)
 page.click('#free');before=page.evaluate('headquartersApp.camera.position.toArray()');page.keyboard.down('w');page.wait_for_timeout(400);page.keyboard.up('w');check('WASD free camera',before!=page.evaluate('headquartersApp.camera.position.toArray()'))
 for view in ['overview','front','top','low','entrance','garden','bridge','roof','steps','trees','grass','stairs','main','annex']:
  page.evaluate('(v)=>headquartersApp.view(v)',view);check('valid view '+view,page.evaluate('headquartersApp.camera.position.toArray().every(Number.isFinite)'))
 for id in ['main','annex','bridge','main-stairs']:
  page.evaluate('(id)=>headquartersApp.isolate(id)',id)
  check('isolation '+id,page.evaluate('(id)=>headquartersApp.model.groups.get(id).visible',id))
  with page.expect_download(timeout=120000) as dl:page.click('#export-part')
  path=OUT/('henglian-'+id+'.glb');dl.value.save_as(path);data=path.read_bytes();size=struct.unpack_from('<I',data,12)[0];doc=json.loads(data[20:20+size]);names=[n.get('name','') for n in doc['nodes']];check('independent GLB '+id,data[:4]==b'glTF' and id in names and all(other not in names for other in ['main','annex','bridge'] if other!=id))
 check('real foliage without refined canopy blobs',page.evaluate("(()=>{let leaves=0,blobs=0;headquartersApp.model.root.traverse(o=>{if(o.isInstancedMesh&&o.material.name.startsWith('foliage-'))leaves+=o.count;if(o.isInstancedMesh&&o.material.name==='leaf')blobs+=o.count});return leaves>90000&&blobs===0})()"))
 check('real curved grass blades',page.evaluate("headquartersApp.model.root.getObjectByName('Curved botanical grass tufts').count===132000&&headquartersApp.model.manifest.ecology.grassBlades===792000"))
 check('complete stair flights and accessible ramps',page.evaluate("headquartersApp.model.manifest.stairs.internal.map(s=>s.flights).join(',')==='48,32'&&headquartersApp.model.manifest.stairs.riserMax<.17&&headquartersApp.model.manifest.stairs.external.every(s=>s.steps===3&&s.ramp.slope==='1:12')"))
 page.evaluate("headquartersApp.view('overview')");page.uncheck('#bridge');check('bridge staff toggle',page.evaluate("!headquartersApp.model.root.getObjectByName('Resident 0').visible&&headquartersApp.model.root.getObjectByName('Resident 10').visible"));page.check('#bridge')
 page.uncheck('#people');check('staff toggle',page.evaluate("!headquartersApp.model.root.getObjectByName('Resident 10').visible"));page.check('#people');page.uncheck('#birds');check('birds independent',page.evaluate("!headquartersApp.model.root.getObjectByName('Courtyard bird 0').visible"));page.check('#birds')
 page.select_option('#quality','low');check('quality tier',page.evaluate("headquartersApp.model.quality==='low'"));page.select_option('#quality','high');page.select_option('#time','night');page.wait_for_timeout(500);page.screenshot(path=str(OUT/'03-night.png'));check('night bounded point lights',page.evaluate('headquartersApp.metrics().pointLights===6'));page.select_option('#time','morning')
 simulation=page.evaluate('''()=>{const T=headquartersApp.THREE,m=CorporateHeadquartersModule.create({THREE:T}),bounds=new T.Box3().setFromObject(m.root);let pure=true,finite=true;m.root.traverse(o=>{if(o.isCamera||o.isLight)pure=false;if(o.isMesh){for(const a of Object.values(o.geometry.attributes))finite&&=a.array.every(Number.isFinite)}});let bridgeHeight=true,contained=true,continuous=true,coreClear=true,doorMoved=false,previous=m.root.getObjectByName('Resident 0').position.clone(),door=m.root.getObjectByName('main sensed door -1'),doorX=door.position.x;for(let i=0;i<800;i++){m.update(.25);const v=m.root.getObjectByName('Resident 0').position;continuous&&=v.distanceTo(previous)<.3;previous.copy(v);doorMoved||=Math.abs(door.position.x-doorX)>.05;for(let j=0;j<22;j++){const p=m.root.getObjectByName('Resident '+j).position;contained&&=Math.abs(p.x)<55&&Math.abs(p.z)<55;if(j<8){bridgeHeight&&=Math.abs(p.y-37.07)<.001;coreClear&&=!(p.x>18.5&&p.x<23.5&&p.z>-.5&&p.z<6.5)}}}const out={pure,finite,bridgeHeight,contained,continuous,coreClear,doorMoved,square:Math.abs(bounds.max.x-bounds.min.x-112)<.01&&Math.abs(bounds.max.z-bounds.min.z-112)<.01,height:Math.abs(bounds.max.y-100)<.01};m.dispose();m.dispose();out.disposal=m.disposed&&m.root.children.length===0;const scaled=CorporateHeadquartersModule.create({THREE:T,blockSize:84,coarse:true});const sb=new T.Box3().setFromObject(scaled.root);out.scalable=Math.abs(sb.max.x-sb.min.x-84)<.01;scaled.dispose();return out}''')
 for k,v in simulation.items():check('200s simulation / '+k,v)
 page.evaluate("headquartersApp.view('overview')");page.wait_for_timeout(400)
 bench=page.evaluate('''()=>new Promise(resolve=>{const a=headquartersApp,dt=[],start=performance.now();let prev=start;function f(now){const e=now-start;if(e>350)dt.push(now-prev);prev=now;a.camera.position.set(Math.sin(e*.0004)*240,170,Math.cos(e*.0004)*240);a.camera.lookAt(a.controls.target);if(e<6500)requestAnimationFrame(f);else{dt.sort((a,b)=>a-b);resolve({fps:1000/(dt.reduce((a,b)=>a+b,0)/dt.length),p95_ms:dt[Math.floor(dt.length*.95)],metrics:a.metrics(),viewport:[innerWidth,innerHeight],userAgent:navigator.userAgent})}}requestAnimationFrame(f)})''');(OUT/'performance.json').write_text(json.dumps(bench,indent=2),encoding='utf8');check('interactive benchmark above 30 FPS',bench['fps']>30)
 page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(300);page.evaluate("headquartersApp.view('overview')");page.wait_for_timeout(300);page.screenshot(path=str(OUT/'03-mobile.png'));check('mobile page fits viewport',page.evaluate('document.documentElement.scrollWidth===innerWidth'))
 if page.locator('#panel-body').is_hidden():page.click('#collapse')
 check('mobile controls expand',page.locator('#time').is_visible());check('no browser errors',not errors)
 (OUT/'verification.json').write_text(json.dumps({'checks':checks,'errors':errors,'benchmark':bench},indent=2),encoding='utf8');ctx.close()
